require_once __DIR__.'/../includes/auth.php';
require_once __DIR__.'/_helper.php';
bk_require_access($pdo);
if(user_role()==='kepala_sekolah'){http_response_code(403);exit('Mode monitoring tidak dapat mencatat kunjungan BK.');}

$q=trim((string)($_GET['q']??''));
$kelasId=max(0,(int)($_GET['kelas_id']??0));
$jenis=(string)($_GET['jenis']??'');
$perPageInput=(int)($_GET['per_page']??20);$perPage=in_array($perPageInput,[10,20,50,100],true)?$perPageInput:20;
$page=max(1,(int)($_GET['page']??1));
$where=['bk.tahun_pelajaran_id=(SELECT id FROM tahun_pelajaran WHERE aktif=1 ORDER BY id DESC LIMIT 1)'];$params=[];
if($q!==''){ $like='%'.$q.'%';$where[]='(s.nama LIKE ? OR s.nis LIKE ? OR s.nisn LIKE ?)';array_push($params,$like,$like,$like); }
if($kelasId>0){$where[]='bk.kelas_id=?';$params[]=$kelasId;}
if(in_array($jenis,['konseling','konsultasi','rujukan','administratif','lainnya'],true)){$where[]='bk.jenis_kunjungan=?';$params[]=$jenis;}
if(user_role()==='guru_bk'){$gid=bk_current_guru_id($pdo);$where[]='bk.petugas_id=?';$params[]=$gid;}
$classes=$pdo->query("SELECT id,nama FROM master_kelas WHERE aktif=1 ORDER BY tingkat,urutan,nama")->fetchAll();
$cnt=$pdo->prepare('SELECT COUNT(*) FROM bk_kunjungan bk JOIN siswa s ON s.id=bk.siswa_id WHERE '.implode(' AND ',$where));$cnt->execute($params);$total=(int)$cnt->fetchColumn();
$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);$offset=($page-1)*$perPage;
$sql='SELECT bk.*,s.nis,s.nisn,s.nama,mk.nama kelas,g.nama petugas FROM bk_kunjungan bk JOIN siswa s ON s.id=bk.siswa_id LEFT JOIN master_kelas mk ON mk.id=bk.kelas_id LEFT JOIN guru g ON g.id=bk.petugas_id WHERE '.implode(' AND ',$where).' ORDER BY bk.tanggal DESC,bk.id DESC LIMIT '.$perPage.' OFFSET '.$offset;
$st=$pdo->prepare($sql);$st->execute($params);$rows=$st->fetchAll();
function bkq(array $c=[]):string{$b=$_GET??[];unset($b['page']);foreach($c as $k=>$v){if($v===null)unset($b[$k]);else$b[$k]=$v;}return http_build_query($b);}
$page_title='Kunjungan BK';require_once __DIR__.'/../layouts/header.php';require_once __DIR__.'/../layouts/sidebar.php';
?>
