<script src="<?=BASE_URL?>assets/js/scanner_sound.js"></script><script>
const soundCtl=SPLASMA_SCANNER_SOUND.bind("soundToggle");
const BASE=<?=json_encode(BASE_URL)?>,CSRF=<?=json_encode(csrf_token())?>;const $=id=>document.getElementById(id);let stream=null,loop=null,lastCode='',lastAt=0,detector=null,qrDecoderPromise=null,usbBuffer='',usbLastAt=0,usbTimer=null;const USB_BURST_MAX_GAP=90,USB_FLUSH_DELAY=140;
function msg(t,type='success'){const el=$('msg');el.className='alert '+(type==='error'?'alert-danger':type==='neutral'?'alert-info':'alert-success');el.innerHTML=t;el.style.display='block'}
function result(t,type='neutral'){const el=$('result');el.className='scan-result '+type;el.innerHTML=t}
function esc(s){return String(s??'').replace(/[&<>'"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[m]))}
function beep(ok=true){try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const c=new C(),o=c.createOscillator(),g=c.createGain();o.frequency.value=ok?880:220;g.gain.value=.035;o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+(ok?.09:.16))}catch(e){}}
$('soundToggle').onclick=()=>{const b=$('soundToggle'),on=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',String(on));b.classList.toggle('on',on);b.classList.toggle('off',!on);b.querySelector('i').className=on?'bi bi-volume-up-fill':'bi bi-volume-mute-fill';b.querySelector('span').textContent=on?'Suara ON':'Suara OFF'};
async function record(qr,metode){qr=(qr||'').trim();if(!qr)return;const fd=new URLSearchParams({action:'scan',kode_qr:qr,metode,jenis_kunjungan:$('jenis').value,keterangan_singkat:$('ket').value,csrf_token:CSRF});try{const r=await fetch(BASE+'bk/kunjungan_api.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:fd,cache:'no-store'});const d=await r.json();if(d.ok){result('<strong>'+esc(d.nama)+'</strong> · '+esc(d.kelas)+'<br>Kunjungan BK tercatat '+esc(d.waktu)+' WIB. <strong>Status kehadiran dan sholat tidak berubah.</strong>','success');msg('<strong>Kunjungan tercatat.</strong> '+esc(d.nama)+' · '+esc(d.waktu)+' WIB.','success');if($('soundToggle').getAttribute('aria-pressed')==='true')beep(true);$('usb').value='';$('search').value='';$('results').innerHTML=''}else if(d.duplicate){result('<strong>'+esc(d.nama||'Siswa')+'</strong><br>Sudah tercatat dalam 60 detik terakhir.','error');if($('soundToggle').getAttribute('aria-pressed')==='true')beep(false)}else{result(esc(d.message||'Gagal mencatat kunjungan.'),'error');msg(esc(d.message||'Gagal mencatat kunjungan.'),'error');if($('soundToggle').getAttribute('aria-pressed')==='true')beep(false)}}catch(e){result('Tidak dapat terhubung ke server.','error');msg('Tidak dapat terhubung ke server.','error')}}
function clearUsbBuffer(){usbBuffer='';if(usbTimer){clearTimeout(usbTimer);usbTimer=null}}
function processUsbBuffer(){const code=usbBuffer.trim();clearUsbBuffer();if(code){$('usb').value=code;record(code,'USB')}}
function usbKeyCapture(e){const target=e.target;if(target&&(['INPUT','TEXTAREA','SELECT'].includes(target.tagName))&&target!==$('usb'))return;const now=performance.now();if(e.key==='Enter'||e.key==='Tab'){if(usbBuffer){e.preventDefault();processUsbBuffer()}return}if(typeof e.key!=='string'||e.key.length!==1)return;if(usbBuffer&&(now-usbLastAt)>USB_BURST_MAX_GAP)clearUsbBuffer();usbBuffer+=e.key;usbLastAt=now;if(usbTimer)clearTimeout(usbTimer);usbTimer=setTimeout(()=>{if(usbBuffer.length>=3)processUsbBuffer();else clearUsbBuffer()},USB_FLUSH_DELAY)}
document.addEventListener('keydown',usbKeyCapture,true);$('usb').addEventListener('focus',()=>$('usbStatus').innerHTML='<strong>🔌 Scanner USB siap.</strong> Scan QR siswa; hasil akan diproses otomatis.');$('usb').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();record(e.target.value,'USB')}});
async function loadQrFallback(){if(window.BarcodeDetector){window.__qrDecoderReady=true;$('qrDecoderStatus').textContent='Pembaca QR: BarcodeDetector tersedia. Fallback jsQR akan digunakan bila diperlukan.';return true}if(window.jsQR){window.__qrDecoderReady=true;$('qrDecoderStatus').textContent='Pembaca QR: jsQR fallback siap.';return true}if(qrDecoderPromise)return qrDecoderPromise;qrDecoderPromise=new Promise((resolve,reject)=>{ $('qrDecoderStatus').textContent=navigator.onLine?'Menyiapkan pembaca QR fallback…':'Fallback QR belum tersedia offline.';const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/jsqr@1.4.0/dist/jsQR.js';s.async=true;s.onload=()=>{if(window.jsQR){window.__qrDecoderReady=true;$('qrDecoderStatus').textContent='Pembaca QR: jsQR fallback siap.';resolve(true)}else reject(new Error('jsQR tidak tersedia'))};s.onerror=()=>reject(new Error('Gagal memuat jsQR'));document.head.appendChild(s)}).catch(e=>{qrDecoderPromise=null;$('qrDecoderStatus').textContent='Fallback QR tidak tersedia. Gunakan browser yang mendukung BarcodeDetector atau scanner USB.';return false});return qrDecoderPromise}
$('prepareDecoder').onclick=async()=>{const b=$('prepareDecoder');b.disabled=true;const ok=await loadQrFallback();msg(ok?'Fallback decoder QR siap.':'Fallback decoder belum tersedia.',''+(ok?'success':'error'));b.disabled=false};
function canvasCropSquare(source,ctx,canvas){const w=source.width||0,h=source.height||0;if(!w||!h)return false;const side=Math.floor(Math.min(w,h)*.82),sx=Math.floor((w-side)/2),sy=Math.floor((h-side)/2);canvas.width=Math.min(960,Math.max(320,side));canvas.height=canvas.width;ctx.drawImage(source,sx,sy,side,side,0,0,canvas.width,canvas.height);return true}
async function decodeQrFrame(video,fullCanvas,fullCtx,cropCanvas,cropCtx){let code=null;if(window.BarcodeDetector){try{detector=detector||new BarcodeDetector({formats:['qr_code']});const n=await detector.detect(fullCanvas);if(n.length)code=n[0].rawValue}catch(e){}if(!code&&canvasCropSquare(video,cropCtx,cropCanvas)){try{const n=await detector.detect(cropCanvas);if(n.length)code=n[0].rawValue}catch(e){}}}if(!code&&window.jsQR){try{const im=fullCtx.getImageData(0,0,fullCanvas.width,fullCanvas.height),d=window.jsQR(im.data,im.width,im.height,{inversionAttempts:'attemptBoth'});if(d)code=d.data}catch(e){}if(!code&&canvasCropSquare(video,cropCtx,cropCanvas)){try{const im=cropCtx.getImageData(0,0,cropCanvas.width,cropCanvas.height),d=window.jsQR(im.data,im.width,im.height,{inversionAttempts:'attemptBoth'});if(d)code=d.data}catch(e){}}}return code}
async function detectCameras(){const sel=$('cameraSelect'),count=$('cameraCount');sel.disabled=true;sel.innerHTML='<option value="">Mendeteksi kamera…</option>';count.textContent='Mendeteksi…';if(!window.isSecureContext){count.textContent='Butuh HTTPS/localhost';sel.innerHTML='<option value="">HTTPS atau localhost diperlukan</option>';msg('Untuk akses kamera, buka aplikasi melalui <strong>HTTPS</strong> atau <strong>localhost</strong>.','error');return}if(!navigator.mediaDevices?.getUserMedia||!navigator.mediaDevices?.enumerateDevices){count.textContent='Tidak didukung';sel.innerHTML='<option value="">Browser tidak mendukung kamera</option>';msg('Browser tidak menyediakan API kamera. Gunakan Chrome/Edge/Firefox terbaru atau scanner USB.','error');return}try{const permissionStream=await navigator.mediaDevices.getUserMedia({video:true,audio:false});permissionStream.getTracks().forEach(t=>t.stop());const devices=await navigator.mediaDevices.enumerateDevices(),cams=devices.filter(d=>d.kind==='videoinput');sel.innerHTML='';if(!cams.length){count.textContent='0 kamera';sel.innerHTML='<option value="">Tidak ada kamera terdeteksi</option>';msg('Tidak ada kamera terdeteksi. Jika memakai scanner USB QR, gunakan kolom Input QR / Scanner USB.','error');return}cams.forEach((d,i)=>{const o=document.createElement('option');o.value=d.deviceId;o.textContent=d.label||`Kamera ${i+1}`;sel.appendChild(o)});sel.disabled=false;count.textContent=`${cams.length} kamera terdeteksi`;msg(`<strong>${cams.length} kamera terdeteksi.</strong> Pilih kamera yang diinginkan lalu tekan Aktifkan Kamera.`,'success')}catch(e){count.textContent='Izin kamera ditolak/gagal';sel.innerHTML='<option value="">Tidak dapat membaca kamera</option>';msg('Browser belum memberikan izin kamera. Izinkan kamera untuk situs ini, lalu tekan Deteksi Kamera lagi.','error')}}
$('detectCameras').onclick=detectCameras;
$('startCamera').onclick=async()=>{if(!window.isSecureContext){msg('Kamera browser memerlukan HTTPS atau localhost.','error');return}if(!navigator.mediaDevices?.getUserMedia){msg('Browser tidak menyediakan akses kamera. Gunakan scanner USB.','error');return}if(!$('cameraSelect').value){await detectCameras();if(!$('cameraSelect').value)return}if(!window.__qrDecoderReady){const ok=await loadQrFallback();if(!ok&& !window.BarcodeDetector){msg('Pembaca QR belum tersedia. Gunakan scanner USB atau siapkan decoder saat online.','error');return}}try{if(stream)stream.getTracks().forEach(t=>t.stop());if(loop)cancelAnimationFrame(loop);stream=await navigator.mediaDevices.getUserMedia({video:{deviceId:{exact:$('cameraSelect').value},width:{ideal:1280},height:{ideal:720}},audio:false});$('reader').innerHTML='';const v=document.createElement('video');v.autoplay=true;v.playsInline=true;v.muted=true;v.srcObject=stream;$('reader').appendChild(v);$('startCamera').disabled=true;$('stopCamera').disabled=false;const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d',{willReadFrequently:true}),cropCanvas=document.createElement('canvas'),cropCtx=cropCanvas.getContext('2d',{willReadFrequently:true});let decoding=false,lastFrameAt=0;const tick=async()=>{if(!stream)return;const now=performance.now();if(now-lastFrameAt<120||decoding){loop=requestAnimationFrame(tick);return}lastFrameAt=now;try{if(v.readyState>=2&&v.videoWidth){const scale=Math.min(1,960/v.videoWidth);canvas.width=Math.max(320,Math.round(v.videoWidth*scale));canvas.height=Math.max(240,Math.round(v.videoHeight*scale));ctx.drawImage(v,0,0,canvas.width,canvas.height);decoding=true;const code=await decodeQrFrame(v,canvas,ctx,cropCanvas,cropCtx);decoding=false;if(code&&(code!==lastCode||Date.now()-lastAt>2500)){lastCode=code;lastAt=Date.now();await record(code,'QR')}}}catch(e){decoding=false}loop=requestAnimationFrame(tick)};tick();try{const track=stream.getVideoTracks()[0],caps=track?.getCapabilities?track.getCapabilities():{};if(caps.focusMode?.includes('continuous'))await track.applyConstraints({advanced:[{focusMode:'continuous'}]})}catch(e){}msg('Kamera aktif. Arahkan QR siswa ke kamera.','success')}catch(e){msg('Kamera tidak dapat digunakan. Pastikan kamera tidak sedang dipakai aplikasi lain dan izin kamera sudah diberikan.','error')}};
$('stopCamera').onclick=()=>{if(loop)cancelAnimationFrame(loop);loop=null;if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}$('reader').innerHTML='<div class="scanner-placeholder"><div class="placeholder-icon">■</div><strong>Kamera dihentikan</strong><span>Scanner USB tetap dapat digunakan.</span></div>';$('startCamera').disabled=false;$('stopCamera').disabled=true};
let searchTimer;$('search').addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(async()=>{const q=$('search').value.trim();if(q.length<2){$('results').innerHTML='';return}try{const r=await fetch(BASE+'bk/kunjungan_api.php?action=lookup&q='+encodeURIComponent(q),{cache:'no-store'}),d=await r.json();$('results').innerHTML=(d.data||[]).map(s=>'<button type="button" class="btn btn-light w-100 text-start" style="margin-top:6px" data-qr="'+esc(s.kode_qr)+'"><strong>'+esc(s.nama)+'</strong><div style="font-size:11px">'+esc(s.nis)+' · '+esc(s.nisn)+' · '+esc(s.kelas)+'</div></button>').join('')||'<div class="text-muted" style="padding:8px">Siswa tidak ditemukan.</div>';document.querySelectorAll('#results [data-qr]').forEach(b=>b.onclick=()=>record(b.dataset.qr,'MANUAL'))}catch(e){$('results').innerHTML='<div class="text-danger" style="padding:8px">Pencarian gagal.</div>'}},250)});
(async()=>{if(!('BarcodeDetector'in window))loadQrFallback().catch(()=>{});else{$('qrDecoderStatus').textContent='Pembaca QR: BarcodeDetector tersedia.'}detectCameras();$('usb').focus()})();
</script><?php require_once __DIR__.'/../layouts/footer.php'; ?>
